import{_ as t,c as n,o as a,a3 as o}from"./chunks/framework.Cc9k46oU.js";const y=JSON.parse('{"title":"SyncAdmin: Vue 3 Back-Office Framework Optimized for AI Integration","description":"An intelligent admin dashboard template built on Vue 3, Vite, and TypeScript. Supports enterprise system development through AI agent monitoring, dynamic data visualization, and granular permission management.","frontmatter":{"title":"SyncAdmin: Vue 3 Back-Office Framework Optimized for AI Integration","description":"An intelligent admin dashboard template built on Vue 3, Vite, and TypeScript. Supports enterprise system development through AI agent monitoring, dynamic data visualization, and granular permission management.","head":[["meta",{"name":"keywords","content":"SyncAdmin, Vue 3, Vite, TypeScript, admin system template, back-office development, admin dashboard, frontend development, AI dashboard, enterprise system, Pinia, i18n, permission management, theme customization, UI framework, ERP system, CRM system, data visualization, Empasy, SyncSeries"}],["meta",{"property":"og:title","content":"SyncAdmin: Vue 3 Back-Office Framework Optimized for AI Integration"}],["meta",{"property":"og:description","content":"An intelligent admin dashboard template built on Vue 3, Vite, and TypeScript."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/syncadmin/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/syncadmin/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncadmin/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncadmin/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncadmin/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncadmin/"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"SyncAdmin: Vue 3 Back-Office Framework Optimized for AI Integration | Empasy Docs"}],["meta",{"property":"og:description","content":"An intelligent admin dashboard template built on Vue 3, Vite, and TypeScript. Supports enterprise system development through AI agent monitoring, dynamic data visualization, and granular permission management."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/syncadmin/"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"SyncAdmin: Vue 3 Back-Office Framework Optimized for AI Integration | Empasy Docs"}],["meta",{"name":"twitter:description","content":"An intelligent admin dashboard template built on Vue 3, Vite, and TypeScript. Supports enterprise system development through AI agent monitoring, dynamic data visualization, and granular permission management."}]],"order":1,"dir":{"order":3}},"headers":[],"relativePath":"en/syncadmin/index.md","filePath":"en/syncadmin/index.md","lastUpdated":1795293539000}'),i={name:"en/syncadmin/index.md"};function s(d,e,r,c,l,m){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="syncadmin-frontend-standard-for-intelligent-back-office-systems-archive" tabindex="-1">SyncAdmin: Frontend Standard for Intelligent Back-Office Systems (Archive) <a class="header-anchor" href="#syncadmin-frontend-standard-for-intelligent-back-office-systems-archive" aria-label="Permalink to “SyncAdmin: Frontend Standard for Intelligent Back-Office Systems (Archive)”">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Enterprise Frontend Standard Consolidation Notice</strong>: The design assets and component system of <code>SyncAdmin</code> have been fully internalized into the <strong><code>admin/</code> (Vue 3 + Vben Admin + DB Single-Source Dynamic Routing)</strong> standard frontend architecture across the 11 SyncSeries enterprise products (<code>SyncVerse</code>, <code>SyncInsight</code>, <code>SyncLLM</code>, <code>SyncAPIM</code>, <code>SyncWatch</code>, <code>SyncBoot</code>, <code>SyncCMS</code>, <code>SyncShop</code>, <code>SyncOps</code>, <code>SyncETA</code>, <code>SyncCrawl</code>).</p></div><p>SyncAdmin is an enterprise management system frontend standard designed on Vue 3, Vite, and TypeScript. Beyond a simple data CRUD interface, it integrates organically with the 11 SyncSeries AI agents (<code>SyncVerse</code>, <code>SyncInsight</code>, <code>SyncLLM</code>, <code>SyncAPIM</code>, <code>SyncWatch</code>, <code>SyncBoot</code>, <code>SyncCMS</code>, <code>SyncShop</code>, <code>SyncOps</code>, <code>SyncETA</code>, <code>SyncCrawl</code>) to provide an intelligent dashboard environment capable of monitoring and controlling system status.</p><h2 id="_1-ai-friendly-frontend-architecture" tabindex="-1">1. AI-Friendly Frontend Architecture <a class="header-anchor" href="#_1-ai-friendly-frontend-architecture" aria-label="Permalink to “1. AI-Friendly Frontend Architecture”">​</a></h2><p>Built on a modern web technology stack, it features a structure optimized for data-driven decision-making and AI model integration.</p><ul><li><strong>Modern Tech Stack</strong>: Delivers fast, lightweight rendering performance based on Vue 3 (Composition API), Vite, and Pinia, displaying large volumes of log data and AI analysis results on screen without latency.</li><li><strong>Dynamic UI Composition</strong>: Includes built-in reusable components that respond flexibly to construct layouts even when data structures change or AI agents return new formats of analysis results.</li><li><strong>Monorepo-Based Management</strong>: Uses pnpm and Turborepo to efficiently manage code across large-scale projects and complex systems combining multiple AI services.</li></ul><h2 id="_2-core-operations-and-management-features" tabindex="-1">2. Core Operations and Management Features <a class="header-anchor" href="#_2-core-operations-and-management-features" aria-label="Permalink to “2. Core Operations and Management Features”">​</a></h2><p>Provides essential enterprise management capabilities out of the box to accelerate development speed.</p><ul><li><strong>Intelligent Access Control &amp; DB Dynamic Routing</strong>: Beyond simple page-level access control, it natively supports <code>PermissionModeEnum.BACK</code> dynamic routing from a database Single Source of Truth (<code>sys_permission</code>, <code>sys_role_permission</code>) and granular button-level permissions (RBAC).</li><li><strong>Zero-Mock Real-Data Integration</strong>: Integrates transparently 1:1 with backend enterprise-standard Canonical URLs (<code>/api/v1/{product}/...</code>) without hardcoded dummy data, and delivers a consistent enterprise UI through high-level standard components (<code>BasicTable</code>, <code>BasicModal</code>, <code>BasicForm</code>, <code>BasicDrawer</code>).</li><li><strong>Multilingual &amp; Theme Support</strong>: Natively supports multilingual environments via an internationalization (i18n) module, and seamlessly provides theme customization and dark mode aligned with corporate brand guidelines.</li></ul><h2 id="_3-adoption-and-use-cases" tabindex="-1">3. Adoption and Use Cases <a class="header-anchor" href="#_3-adoption-and-use-cases" aria-label="Permalink to “3. Adoption and Use Cases”">​</a></h2><p>SyncAdmin integrates and provides all UI assets required to build internal systems, serving as the foundation for a wide range of B2B solutions.</p><ul><li><strong>Unified Control Dashboard</strong>: Serves as a control center that visualizes AI agent activity logs, status, and data collection progress in real time.</li><li><strong>Enterprise Core Solutions</strong>: Significantly reduces development time for systems requiring complex business logic and numerous input forms, such as ERP, CRM, and HR management.</li><li><strong>Data Analytics Views</strong>: Supports diverse UI frameworks (such as Ant Design Vue) and charting libraries, making it easy to build report views where data can be understood intuitively.</li></ul><hr><h2 id="_4-enterprise-11-product-frontend-admin-standard-mapping-status" tabindex="-1">4. Enterprise 11-Product Frontend (<code>admin/</code>) Standard Mapping Status <a class="header-anchor" href="#_4-enterprise-11-product-frontend-admin-standard-mapping-status" aria-label="Permalink to “4. Enterprise 11-Product Frontend (admin/) Standard Mapping Status”">​</a></h2><p>The frontend package and dynamic permission API mapping specifications for the 11 enterprise products in which the <code>SyncAdmin</code> architecture is currently internalized are as follows:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Product</th><th style="text-align:left;">Frontend Package Name (<code>package.json</code>)</th><th style="text-align:center;">Routing Mode</th><th style="text-align:left;">Dynamic Menu &amp; Permission Authorization Canonical API</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SyncVerse</strong></td><td style="text-align:left;"><code>@empasy/sync-verse-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/verse/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncInsight</strong></td><td style="text-align:left;"><code>@empasy/sync-insight-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/insight/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncLLM</strong></td><td style="text-align:left;"><code>@empasy/sync-llm-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/llm/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncAPIM</strong></td><td style="text-align:left;"><code>@empasy/sync-apim-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/apim/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncWatch</strong></td><td style="text-align:left;"><code>@empasy/sync-watch-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/watch/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncBoot</strong></td><td style="text-align:left;"><code>@empasy/sync-boot-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/boot/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncCMS</strong></td><td style="text-align:left;"><code>@empasy/sync-cms-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/cms/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncShop</strong></td><td style="text-align:left;"><code>@empasy/sync-shop-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/shop/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncOps</strong></td><td style="text-align:left;"><code>@empasy/sync-ops-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/ops/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncETA</strong></td><td style="text-align:left;"><code>@empasy/sync-eta-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/eta/sys/permission/getUserPermissionByToken</code></td></tr><tr><td style="text-align:left;"><strong>SyncCrawl</strong></td><td style="text-align:left;"><code>@empasy/sync-crawl-admin</code></td><td style="text-align:center;"><code>BACK</code></td><td style="text-align:left;"><code>/api/v1/crawl/sys/permission/getUserPermissionByToken</code></td></tr></tbody></table>',16)])])}const g=t(i,[["render",s]]);export{y as __pageData,g as default};
